        map.put(k,v);
    }

    @SuppressWarnings("unchecked")
    @Override 
    public void putAll(GrammaticalTermMap<T> other) {
        if(isSkinny)
            throw new RuntimeException("This map is not able to modify");
        map.putAll(((GrammaticalTermMapImpl<T>)other).map);
    }

    @Override
    public boolean isEmpty() {
        return map.isEmpty();
    }

    /**
